/**
 * @file Image loading for the game client.
 *
 * Resources are looked up in the manifest served by `/api/resources` (so a
 * sheet may be an SVG generated by the engine or a PNG imported by the
 * creator). Each image is decoded once and copied into a canvas at its native
 * size: drawing from a bitmap canvas is much faster than drawing an SVG image
 * every frame, and it freezes the rasterisation so pixels stay crisp.
 *
 * Converted resources: images in an older layout (legacy autotiles and
 * tilesets, 16 px chipsets, character and face sheets) are composed into
 * standard sheets from their layout table (`shared/conversions.ts`). A tileset
 * references a converted sheet with a virtual name `<image>~<slot>`; 16 px
 * character and face sheets are converted automatically under their own name.
 */
import { conversionFor, parseVirtualName, type SheetLayout } from '../../shared/conversions.js';

/** Manifest entry (subset used by the client). */
export interface ResourceEntry {
  id: string;
  kind: string;
  name: string;
  url: string;
  hash: string;
  format: string;
  width: number | null;
  height: number | null;
}

/** A decoded image ready to draw. */
export type Bitmap = HTMLCanvasElement;

/** Delay before an image that failed to load is requested again. */
const RETRY_FAILED_MS = 30_000;
/** Memory the decoded images may take (bytes) before the least recently used ones are dropped. */
const IMAGE_BUDGET = 64 * 1024 * 1024;

/**
 * Loads and caches images by resource id (`kind/name`). The cache keeps a budget: past it, the images
 * least recently asked for are dropped (never those of the map being played), so that the memory does
 * not grow with every map visited. A dropped image is only forgotten, never cleared: a scene still
 * holding it keeps drawing it.
 */
export class AssetStore {
  private manifest = new Map<string, ResourceEntry>();
  /** Images by id, least recently asked for first. */
  private readonly images = new Map<string, Promise<Bitmap | null>>();
  /** When each image that resolved to `null` failed (to try it again later). */
  private readonly failedAt = new Map<string, number>();
  /** Decoded size (bytes) of each loaded image. */
  private readonly bytes = new Map<string, number>();
  /** Scene in which each image was last asked for. */
  private readonly usedIn = new Map<string, number>();
  private scene = 0;
  private total = 0;

  /** @param budget - Bytes the decoded images may take. */
  constructor(private readonly budget = IMAGE_BUDGET) {}

  /** A new map is being loaded: the images it asks for from now on are kept while it is played. */
  beginScene(): void {
    this.scene++;
  }

  /** Bytes taken by the decoded images in the cache (memory checks). */
  get cachedBytes(): number {
    return this.total;
  }

  /** Downloads the resource manifest. */
  async init(): Promise<void> {
    const res = await fetch('/api/resources', { credentials: 'same-origin' });
    if (!res.ok) throw new Error(`manifest: HTTP ${res.status}`);
    const body = (await res.json()) as { resources: ResourceEntry[] };
    this.manifest = new Map(body.resources.map((r) => [r.id, r]));
  }

  /**
   * Reads the manifest again (resources uploaded, replaced or deleted since): the images whose file
   * changed are loaded again on their next use.
   */
  async refresh(): Promise<void> {
    const before = this.manifest;
    await this.init();
    for (const id of [...this.images.keys()]) {
      const slash = id.indexOf('/');
      const kind = id.slice(0, slash);
      const name = id.slice(slash + 1);
      const file = `${kind}/${parseVirtualName(name)?.image ?? name}`;
      if (before.get(file)?.hash === this.manifest.get(file)?.hash) continue;
      this.forget(id);
    }
  }

  /** Drops an image from the cache (a scene holding it keeps it). */
  private forget(id: string): void {
    this.images.delete(id);
    this.failedAt.delete(id);
    this.usedIn.delete(id);
    this.total -= this.bytes.get(id) ?? 0;
    this.bytes.delete(id);
  }

  /** An image finished loading: its size counts against the budget. */
  private loaded(id: string, bitmap: Bitmap | null): void {
    const size = bitmap ? bitmap.width * bitmap.height * 4 : 0;
    this.total += size - (this.bytes.get(id) ?? 0);
    this.bytes.set(id, size);
    if (this.total <= this.budget) return;
    // Least recently asked for first; images still loading, or asked for by the current map, stay.
    for (const old of this.images.keys()) {
      if (this.total <= this.budget) break;
      if (this.bytes.has(old) && this.usedIn.get(old) !== this.scene) this.forget(old);
    }
  }

  /** Tells whether a resource exists. */
  has(kind: string, name: string): boolean {
    return this.manifest.has(`${kind}/${name}`);
  }

  /** URL of a resource (with a cache-busting hash), or `null`. */
  url(kind: string, name: string): string | null {
    const entry = this.manifest.get(`${kind}/${name}`);
    return entry ? `${entry.url}?v=${entry.hash}` : null;
  }

  /**
   * Loads an image as a bitmap canvas. Missing or broken images resolve to `null`
   * (the renderer simply skips them).
   * @param kind - Resource folder (e.g. `tilesets`).
   * @param name - File name without extension.
   */
  image(kind: string, name: string): Promise<Bitmap | null> {
    const id = `${kind}/${name}`;
    let pending = this.images.get(id);
    // A failed load (network hiccup) may be tried again, but not on every call: the renderer asks for images each frame.
    const failedAt = this.failedAt.get(id);
    this.usedIn.set(id, this.scene);
    if (!pending || (failedAt !== undefined && Date.now() - failedAt > RETRY_FAILED_MS)) {
      this.failedAt.delete(id);
      const loading = this.load(kind, name);
      pending = loading;
      this.images.delete(id);
      this.images.set(id, loading);
      void loading.then((bitmap) => {
        if (this.images.get(id) !== loading) return;
        if (bitmap === null) this.failedAt.set(id, Date.now());
        this.loaded(id, bitmap);
      });
    } else {
      // Most recently asked for: last in the eviction order.
      this.images.delete(id);
      this.images.set(id, pending);
    }
    return pending;
  }

  private async load(kind: string, name: string): Promise<Bitmap | null> {
    const virtual = parseVirtualName(name);
    const entry = this.manifest.get(`${kind}/${virtual ? virtual.image : name}`);
    if (!entry) return null;
    const bitmap = await loadBitmap(`${entry.url}?v=${entry.hash}`);
    if (!bitmap) return null;
    const layouts = conversionFor(entry.format, bitmap.width, bitmap.height);
    if (!layouts) return bitmap;
    // Plain names of convertible character/face sheets use their first layout.
    const layout = layouts[virtual ? virtual.slot : '0'];
    return layout ? composeSheet(bitmap, layout) : virtual ? null : bitmap;
  }
}

/**
 * Builds a standard sheet from an original image and its layout table.
 * @param source - Original image.
 * @param layout - Copy operations.
 */
export function composeSheet(source: Bitmap, layout: SheetLayout): Bitmap {
  const canvas = document.createElement('canvas');
  canvas.width = layout.width;
  canvas.height = layout.height;
  const ctx = canvas.getContext('2d')!;
  ctx.imageSmoothingEnabled = false;
  for (const op of layout.ops) ctx.drawImage(source, op.sx, op.sy, op.sw, op.sh, op.dx, op.dy, op.dw, op.dh);
  return canvas;
}

/**
 * Decodes an image URL into a canvas of the same size.
 * @param url - Image URL.
 */
export async function loadBitmap(url: string): Promise<Bitmap | null> {
  const img = new Image();
  img.decoding = 'async';
  img.src = url;
  try {
    await img.decode();
  } catch {
    return null;
  }
  const canvas = document.createElement('canvas');
  canvas.width = img.naturalWidth;
  canvas.height = img.naturalHeight;
  const ctx = canvas.getContext('2d');
  if (!ctx) return null;
  ctx.imageSmoothingEnabled = false;
  ctx.drawImage(img, 0, 0);
  return canvas;
}
